package dev.clientcompose

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.contentOrNull

/**
 * Where an island's props hold an entity (spec §2.1). Generated by codegen, as an island
 * descriptor's `entities`.
 *
 * @param path from the props down: property names, "[]" for an array's items, "{}" for a map's values.
 * @param id the property that identifies one.
 * @param properties the entity's properties the island shows, the id among them.
 */
public data class EntityPath(
    val path: List<String>,
    val entity: String,
    val id: String,
    val properties: List<String>,
)

/** What an action changed about one entity (spec §5.3): properties it set, or that it's gone. */
@Serializable
public data class EntityChange(
    val entity: String,
    val id: String,
    /** The properties that changed, with their new values. Empty for a deleted entity. */
    val set: JsonObject = JsonObject(emptyMap()),
    val delete: Boolean = false,
)

/** An island's new entry, for the screen with these exact params (spec §5.3). */
@Serializable
public data class IslandUpdate(
    val screen: String,
    val params: Map<String, String> = emptyMap(),
    val island: IslandEntry,
)

/**
 * What a client knows about the islands it can render: their versions, sent with every request,
 * and where their props hold entities, to apply an action's changes. Get it from a registry:
 * `registry.catalog`.
 */
public data class IslandCatalog(
    val capabilities: Map<String, List<Int>>,
    private val entityPaths: Map<String, List<EntityPath>>,
) {
    /** Where an island version's props hold entities. */
    public fun entities(type: String, version: Int): List<EntityPath> = entityPaths["$type@$version"] ?: emptyList()

    public companion object {
        public val EMPTY: IslandCatalog = IslandCatalog(emptyMap(), emptyMap())
    }
}

/** One action's changes and updates (spec §5.3), applied the same way to every screen a client has. */
public class EffectsBatch(public val effects: ActionEffects, public val catalog: IslandCatalog) {
    /** Whether there's anything for screens: changes or updates. */
    public val touchesScreens: Boolean get() = effects.changes.isNotEmpty() || effects.update.isNotEmpty()

    /**
     * A screen with the changes and updates applied, or null when the client must reload it: a
     * deleted entity held where it can't be removed, or an update the screen can't take.
     */
    public fun apply(response: ScreenResponse, params: Map<String, String>): ScreenResponse? {
        var reload = false
        val islands = response.islands.map { entry ->
            val props = entry.props
            if (entry.status != "ok" || props == null) return@map entry
            var changed: JsonElement = props
            for (path in catalog.entities(entry.type, entry.version)) {
                changed = applyAlong(changed, path, path.path, inArray = false) { reload = true } ?: changed
            }
            entry.copy(props = changed as JsonObject)
        }.toMutableList()
        if (reload) return null
        for (update in effects.update) {
            if (update.screen != response.screen || update.params != params) continue
            val i = islands.indexOfFirst { it.key == update.island.key }
            if (i < 0 || islands[i].status == "pending" || islands[i].type != update.island.type) return null
            islands[i] = update.island
        }
        return response.copy(islands = islands)
    }

    /**
     * Applies the changes to the entities at the end of a path. Returns null for an entity deleted
     * from an array, and calls [reload] when one is deleted from anywhere else.
     */
    private fun applyAlong(
        value: JsonElement,
        path: EntityPath,
        rest: List<String>,
        inArray: Boolean,
        reload: () -> Unit,
    ): JsonElement? {
        val step = rest.firstOrNull()
        if (step == null) {
            val obj = value as? JsonObject ?: return value
            val id = (obj[path.id] as? JsonPrimitive)?.contentOrNull
            val change = effects.changes.firstOrNull { it.entity == path.entity && it.id == id } ?: return value
            if (change.delete) {
                if (!inArray) reload()
                return if (inArray) null else value
            }
            return JsonObject(obj + change.set.filterKeys { it in path.properties })
        }
        val next = rest.drop(1)
        return when {
            step == "[]" && value is JsonArray ->
                JsonArray(value.mapNotNull { applyAlong(it, path, next, inArray = next.isEmpty(), reload) })
            value is JsonObject ->
                JsonObject(
                    value.mapValues { (key, item) ->
                        if (step == "{}" || step == key) applyAlong(item, path, next, inArray = false, reload) ?: item else item
                    },
                )
            else -> value
        }
    }
}
